{
  "name": "NanoScanZ 纳米调焦压电Z轴平台",
  "name_en": "NanoScanZ Nano Focusing Piezo Stage",
  "manufacturer": "Prior Scientific",
  "description": "这是一种用于显微镜或精密定位系统的压电驱动Z轴纳米调焦平台，可在垂直方向进行高分辨率升降与精密对焦，适用于显微成像、焦点扫描和样品的精细Z向定位。",
  "description_en": "A piezo-driven Z-axis nano focusing stage for microscopes or precision positioning systems. It provides high-resolution vertical motion and fine focus control for microscopy, focus scanning, and precise sample positioning along the Z axis.",
  "tag_hints": [
    "piezo Z stage",
    "microscope focusing",
    "nanopositioning",
    "Z-axis positioning",
    "focus scanning",
    "precision microscopy"
  ],
  "actions": [
    {
      "action_name": "auto-move_absolute_async",
      "description": "异步移动到指定绝对Z位置",
      "description_en": "Asynchronously move to a specified absolute Z position."
    },
    {
      "action_name": "auto-move_relative_async",
      "description": "异步按相对位移移动Z轴",
      "description_en": "Asynchronously move the Z axis by a relative offset."
    },
    {
      "action_name": "auto-query",
      "description": "发送控制命令并读取设备响应",
      "description_en": "Send a control command and read the device response."
    },
    {
      "action_name": "auto-zero_position_async",
      "description": "异步回到零位",
      "description_en": "Asynchronously move to the zero position."
    },
    {
      "action_name": "auto-baudrate",
      "description": "获取/设置串口波特率",
      "description_en": "Get/set the serial baud rate."
    },
    {
      "action_name": "auto-moving",
      "description": "获取运动状态",
      "description_en": "Get the motion status."
    },
    {
      "action_name": "auto-idn",
      "description": "获取设备标识",
      "description_en": "Get the device identification."
    },
    {
      "action_name": "auto-position",
      "description": "获取/设置当前Z位置",
      "description_en": "Get/set the current Z position."
    },
    {
      "action_name": "auto-zero_position",
      "description": "回到零位",
      "description_en": "Move to the zero position."
    },
    {
      "action_name": "auto-move_absolute",
      "description": "移动到指定绝对Z位置",
      "description_en": "Move to a specified absolute Z position."
    },
    {
      "action_name": "auto-move_relative",
      "description": "按相对位移移动Z轴",
      "description_en": "Move the Z axis by a relative offset."
    },
    {
      "action_name": "auto-step",
      "description": "获取/设置默认步长",
      "description_en": "Get/set the default step size."
    },
    {
      "action_name": "auto-software_version",
      "description": "获取软件版本",
      "description_en": "Get the software version."
    },
    {
      "action_name": "auto-write",
      "description": "写入原始控制命令",
      "description_en": "Write a raw control command."
    },
    {
      "action_name": "auto-read",
      "description": "读取原始设备响应",
      "description_en": "Read the raw device response."
    }
  ]
}

